---@meta
-- Basalt Lua API type definitions for lua-language-server (LuaLS).
-- The LuaTypeDefinitions unit test checks that this file compiles, that the declared names match the C++ bindings
-- (Basalt/Source/Basalt/Scripting) and that the component fields and their types match the registry; signatures and
-- types outside the component section are kept by hand.
-- The component section between the markers at the end is generated by scripts/generate_docs.py; do not edit it.
-- Semantics, errors and examples: Docs/ScriptingAPI.md.

-- Aliases ----------------------------------------------------------------------------------------------------------

---Key names (case-insensitive): A-Z, D0-D9, Space, Enter, Escape, Tab, Backspace, Left, Right, Up, Down,
---LeftShift, LeftControl, LeftAlt, F1-F12, KP0-KP9, ...
---@alias KeyName string

---Mouse button names (case-insensitive).
---@alias MouseButton "Left"|"Right"|"Middle"|"Button3"|"Button4"|"Button5"|"Button6"|"Button7"

---Gamepad buttons, standard (Xbox-style) layout (case-insensitive).
---@alias GamepadButton "A"|"B"|"X"|"Y"|"LeftBumper"|"RightBumper"|"Back"|"Start"|"Guide"|"LeftThumb"|"RightThumb"|"DPadUp"|"DPadRight"|"DPadDown"|"DPadLeft"

---Gamepad axes: sticks -1..1 (+Y is down), triggers 0..1 (case-insensitive).
---@alias GamepadAxis "LeftX"|"LeftY"|"RightX"|"RightY"|"LeftTrigger"|"RightTrigger"

---What the game asks the mouse cursor to do (case-insensitive): Locked hides it and holds it in the window.
---@alias CursorMode "Normal"|"Hidden"|"Locked"

---Mixer buses; Music, SFX and UI feed Master.
---@alias AudioBus "Master"|"Music"|"SFX"|"UI"

---Horizontal text alignment of UI.Text.
---@alias UIAlign "Left"|"Center"|"Right"

---UI anchor preset names (case-sensitive).
---@alias UIAnchorPreset "TopLeft"|"Top"|"TopRight"|"Left"|"Center"|"Right"|"BottomLeft"|"Bottom"|"BottomRight"

---An anchor preset or a Vec2 of canvas fractions (0..1).
---@alias UIAnchor UIAnchorPreset|Vec2

---Shadow and SSAO quality levels.
---@alias GraphicsQuality "Off"|"Low"|"High"

-- Math types -------------------------------------------------------------------------------------------------------

---2D vector (also canvas positions and sizes). `number * Vec2` works too.
---@class Vec2
---@field x number
---@field y number
---@overload fun(): Vec2
---@overload fun(s: number): Vec2
---@overload fun(x: number, y: number): Vec2
---@operator add(Vec2): Vec2
---@operator sub(Vec2): Vec2
---@operator mul(Vec2): Vec2
---@operator mul(number): Vec2
---@operator div(Vec2): Vec2
---@operator div(number): Vec2
---@operator unm: Vec2
Vec2 = {}

---Length of the vector.
---@return number
function Vec2:Length() end

---Unit vector in the same direction (a zero vector stays zero).
---@return Vec2
function Vec2:Normalized() end

---Dot product.
---@param other Vec2
---@return number
function Vec2:Dot(other) end

---3D vector (positions, directions, Euler angles in radians). `number * Vec3` works too.
---@class Vec3
---@field x number
---@field y number
---@field z number
---@overload fun(): Vec3
---@overload fun(s: number): Vec3
---@overload fun(x: number, y: number, z: number): Vec3
---@operator add(Vec3): Vec3
---@operator sub(Vec3): Vec3
---@operator mul(Vec3): Vec3
---@operator mul(number): Vec3
---@operator div(Vec3): Vec3
---@operator div(number): Vec3
---@operator unm: Vec3
Vec3 = {}

---Length of the vector.
---@return number
function Vec3:Length() end

---Unit vector in the same direction (a zero vector stays zero).
---@return Vec3
function Vec3:Normalized() end

---Dot product.
---@param other Vec3
---@return number
function Vec3:Dot(other) end

---Cross product.
---@param other Vec3
---@return Vec3
function Vec3:Cross(other) end

---Distance between two points.
---@param other Vec3
---@return number
function Vec3:Distance(other) end

---Linear interpolation toward other by t.
---@param other Vec3
---@param t number
---@return Vec3
function Vec3:Lerp(other, t) end

---4D vector; colors are Vec4 RGBA. `number * Vec4` works too.
---@class Vec4
---@field x number
---@field y number
---@field z number
---@field w number
---@overload fun(): Vec4
---@overload fun(s: number): Vec4
---@overload fun(x: number, y: number, z: number, w: number): Vec4
---@operator add(Vec4): Vec4
---@operator sub(Vec4): Vec4
---@operator mul(Vec4): Vec4
---@operator mul(number): Vec4
Vec4 = {}

---Rotation quaternion. Quat() is the identity; q * Vec3 rotates the vector.
---@class Quat
---@field w number
---@field x number
---@field y number
---@field z number
---@overload fun(): Quat
---@overload fun(w: number, x: number, y: number, z: number): Quat
---@operator mul(Quat): Quat
---@operator mul(Vec3): Vec3
Quat = {}

---The identity rotation.
---@return Quat
function Quat.Identity() end

---Rotation from Euler angles in radians.
---@param euler Vec3
---@return Quat
function Quat.FromEuler(euler) end

---Rotation of angle radians around axis (normalized for you).
---@param angle number
---@param axis Vec3
---@return Quat
function Quat.AngleAxis(angle, axis) end

---Rotation that looks along forward (-Z) with the given up (default +Y).
---@param forward Vec3
---@param up? Vec3
---@return Quat
function Quat.LookRotation(forward, up) end

---Spherical interpolation from a to b by t.
---@param a Quat
---@param b Quat
---@param t number
---@return Quat
function Quat.Slerp(a, b, t) end

---Euler angles in radians.
---@return Vec3
function Quat:ToEuler() end

---Unit quaternion.
---@return Quat
function Quat:Normalized() end

---Inverse rotation.
---@return Quat
function Quat:Inverse() end

---Math helpers and the deterministic random generator (seeded from the project's RandomSeed).
---@class Math
---@field Pi number
Math = {}

---Degrees to radians.
---@param degrees number
---@return number
function Math.Radians(degrees) end

---Radians to degrees.
---@param radians number
---@return number
function Math.Degrees(radians) end

---Clamps value to [min, max].
---@param value number
---@param min number
---@param max number
---@return number
function Math.Clamp(value, min, max) end

---Linear interpolation from a to b by t.
---@param a number
---@param b number
---@param t number
---@return number
function Math.Lerp(a, b, t) end

---1, -1 or 0.
---@param value number
---@return number
function Math.Sign(value) end

---Reseeds the generator (an integer or integral float; 32-bit, other integers use their low 32 bits).
---@param seed integer
function Math.Seed(seed) end

---A random number in [0, 1), or in [min, max).
---@return number
---@overload fun(min: number, max: number): number
function Math.Random() end

---A random integer in [min, max].
---@param min integer
---@param max integer
---@return integer
function Math.RandomInt(min, max) end

-- Entities and scenes ----------------------------------------------------------------------------------------------

---A handle to a scene entity, safe to hold: using a destroyed entity raises an error (check IsValid).
---@class Entity
---@field ID integer Unique 64-bit ID (read-only)
---@field Name string Display name
---@field Translation Vec3 Local position (relative to the parent)
---@field Rotation Quat Local rotation
---@field EulerAngles Vec3 Local rotation as Euler angles in radians
---@field Scale Vec3 Local scale
---@field WorldPosition Vec3 World-space position
Entity = {}

---Whether the entity still exists.
---@return boolean
function Entity:IsValid() end

---World-space forward axis (-Z).
---@return Vec3
function Entity:GetForward() end

---World-space right axis (+X).
---@return Vec3
function Entity:GetRight() end

---World-space up axis (+Y).
---@return Vec3
function Entity:GetUp() end

---Rotates the entity to face a world position (up defaults to +Y).
---@param target Vec3
---@param up? Vec3
function Entity:LookAt(target, up) end

---Whether the entity has the component.
---@param name ComponentName
---@return boolean
function Entity:HasComponent(name) end

---Adds a component, with optional field values (Tag and Transform always exist).
---@param name ComponentName
---@param data? table
function Entity:AddComponent(name, data) end

---Removes a component (Tag and Transform cannot be removed).
---@param name ComponentName
function Entity:RemoveComponent(name) end

---Sets the given fields of an existing component (others unchanged); invalid fields raise errors.
---@param name ComponentName
---@param data table
function Entity:SetComponent(name, data) end

---The parent entity, or nil for a root.
---@return Entity?
function Entity:GetParent() end

---Reparents the entity (nil makes it a root), keeping its world transform.
---@param parent? Entity
function Entity:SetParent(parent) end

---The direct children.
---@return Entity[]
function Entity:GetChildren() end

---The first descendant with this name (depth-first), or nil.
---@param name string
---@return Entity?
function Entity:FindChild(name) end

---Adds a force to the dynamic body.
---@param force Vec3
function Entity:AddForce(force) end

---Adds an impulse to the dynamic body.
---@param impulse Vec3
function Entity:AddImpulse(impulse) end

---Adds a torque to the dynamic body.
---@param torque Vec3
function Entity:AddTorque(torque) end

---Sets the body's linear velocity.
---@param velocity Vec3
function Entity:SetLinearVelocity(velocity) end

---The body's linear velocity (for a character: how fast it moved in the last step).
---@return Vec3
function Entity:GetLinearVelocity() end

---Sets the body's angular velocity.
---@param velocity Vec3
function Entity:SetAngularVelocity(velocity) end

---The body's angular velocity.
---@return Vec3
function Entity:GetAngularVelocity() end

---Whether the body is asleep (no longer simulated until something wakes it; see RigidBody.AllowSleeping). False for static bodies; nil for entities without a body.
---@return boolean?
function Entity:IsSleeping() end

---Hinge angle (degrees) or slider offset (meters) of the Joint this entity holds; nil otherwise.
---@return number?
function Entity:GetJointPosition() end

---Rotation (Euler degrees) of the cone or six-DOF Joint this entity holds; nil otherwise.
---@return Vec3?
function Entity:GetJointRotation() end

---Whether the Joint this entity holds is a live constraint.
---@return boolean
function Entity:HasJoint() end

---Walks the CharacterController with this velocity (m/s) until the next call.
---@param velocity Vec3
function Entity:Move(velocity) end

---Whether the character stands on walkable ground.
---@return boolean
function Entity:IsGrounded() end

---Normal of the ground the character touches; nil in the air or without a character.
---@return Vec3?
function Entity:GetGroundNormal() end

---Plays the AudioSource from the start; false (logged) when it cannot play.
---@return boolean
function Entity:PlayAudio() end

---Stops the AudioSource.
function Entity:StopAudio() end

---Whether the AudioSource is playing.
---@return boolean
function Entity:IsAudioPlaying() end

---The Doppler pitch factor of the AudioSource from the last update (the shift its next mix applies): 1 = unshifted,
---also while it is not playing or for a non-spatial source.
---@return number
function Entity:GetAudioDopplerPitch() end

-- Animator graph playback uses each state's Looping flag instead of Animator.Looping.
-- PlayOnStart=false holds the initial state paused until PauseAnimation(false); zero-length states ignore ExitTime.
-- Root motion writes yaw to the entity transform and sends character translation through physics.
-- An unbuilt character drops queued translation with an error; yaw still applies.

---Restarts a clip (nil or empty: the first) at 0; returns success.
---@param clip? string
---@return boolean
function Entity:PlayAnimation(clip) end

---Controls this entity's PropertyAnimation in Play/Simulate. Play restarts, Pause/Resume preserve time,
---Stop samples zero and Seek samples normalized time without changing pause state. Invalid input, sampling failure and calls outside Play/Simulate raise.
---Pause/Resume reject suspended timelines; repair requires a successful sample. Seek repair stays stopped; Play restarts.
---@param action 'Play'|'Pause'|'Resume'|'Stop'|'Seek'
---@param time? number Normalized time in [0,1], default 0
---@return boolean
function Entity:ControlPropertyAnimation(action, time) end

---@class PropertyAnimationStatus
---@field time number Normalized timeline time
---@field playing boolean
---@field failed boolean Whether playback is suspended after a sample failure
---@field error string Last failure, empty when healthy

---Read-only status of this entity's PropertyAnimation in Play/Simulate.
---@return PropertyAnimationStatus
function Entity:GetPropertyAnimationStatus() end

---Crossfades to clip over seconds; returns success.
---@param clip string
---@param seconds number
---@return boolean
function Entity:CrossFadeAnimation(clip, seconds) end

---Persistent blend of two clips, weight 0..1 toward second; returns success.
---@param first string
---@param second string
---@param weight number
---@return boolean
function Entity:BlendAnimations(first, second, weight) end

---Pauses (default) or resumes the Animator.
---@param paused? boolean
function Entity:PauseAnimation(paused) end

---Stops the Animator, disables an active state machine, and shows the rest pose.
function Entity:StopAnimation() end

---Seeks the Animator, leaving the rest pose, and resets graph exit phase to min(seconds, duration)/duration.
---A zero-duration cycle has phase 0. Returns success.
---@param seconds number
---@return boolean
function Entity:SetAnimationTime(seconds) end

---Current clip time in seconds.
---@return number
function Entity:GetAnimationTime() end

---Current clip duration in seconds (0 if none).
---@return number
function Entity:GetAnimationDuration() end

---Whether the Animator's playback is advancing.
---@return boolean
function Entity:IsAnimationPlaying() end

---The Animator's selectable clip names.
---@return string[]
function Entity:GetAnimationClips() end

---Sets a declared Float or Bool parameter. False on a missing parameter, wrong declared type, non-finite value or inactive machine.
---Nil and values other than numbers/booleans raise an argument error.
---@param name string
---@param value number|boolean
---@return boolean
function Entity:SetAnimationParameter(name, value) end

---Latches a declared trigger until a successful transition consumes it; false for an unknown/wrong-type parameter or inactive graph.
---@param name string
---@return boolean
function Entity:SetAnimationTrigger(name) end

---Current state name, or an empty string after Stop, direct playback or a failed graph load.
---@return string
function Entity:GetAnimationState() end

---Plays one of the Animator's BlendSpaces at parameter (x, y), fading from the current pose over fadeSeconds
---(default 0). While that space plays it only moves the parameter (the fade is ignored); a paused or finished one
---restarts. Returns success.
---@param space string
---@param x number
---@param y? number
---@param fadeSeconds? number
---@return boolean
function Entity:PlayBlendSpace(space, x, y, fadeSeconds) end

---Moves the running blend space's parameter (an omitted y keeps the current one); false when no blend space is
---running or it cannot play there (missing space, or no sample weighted at the parameter has a clip).
---@param x number
---@param y? number
---@return boolean
function Entity:SetBlendSpaceParameter(x, y) end

---The running blend space's weight per clip name (0 for clips without weight at the parameter; empty when no
---blend space is running or it cannot play).
---@return table<string, number>
function Entity:GetBlendSpaceWeights() end

---World position, rotation and scale of the first node named joint in the Animator's current pose: the previous
---frame's during OnUpdate, this frame's during OnLateUpdate (with the previous frame's IK solution) and
---OnAnimationEvent (with this frame's). Nil when the node is missing or the model cannot animate
---(logged when the problem appears or changes). Errors without an Animator.
---@param joint string
---@return Vec3? position
---@return Quat? rotation
---@return Vec3? scale
function Entity:GetBoneTransform(joint) end

---Restarts one of the Animator's Layers at time 0, on clip when given (until the layer's configured Clip changes),
---otherwise on its configured Clip. False, changing nothing (logged once until the call succeeds), for an unknown
---layer, an unknown or empty clip name, or when the layer would show nothing.
---@param layer string
---@param clip? string
---@return boolean
function Entity:PlayAnimationLayer(layer, clip) end

---Fades a layer's weight (0..1) linearly over seconds (default 0: at once). False for an unknown layer or an invalid
---weight or time.
---@param layer string
---@param weight number
---@param seconds? number
---@return boolean
function Entity:SetAnimationLayerWeight(layer, weight, seconds) end

---A layer's current weight; nil for an unknown layer.
---@param layer string
---@return number?
function Entity:GetAnimationLayerWeight(layer) end

---Sets an InverseKinematics chain's target until ClearIKTarget: a world position (with an optional world rotation
---for a TwoBone chain's end joint), or an entity followed every frame (matchRotation also takes its rotation for a
---TwoBone chain). Replaces ground placement. False (logged once until the call succeeds) for an unknown chain, a
---non-finite position, a zero rotation or a rotation for a LookAt chain. Errors without an InverseKinematics component
---or with an entity that was destroyed.
---@param chain string
---@param target Vec3|Entity
---@param rotationOrMatch? Quat|boolean
---@return boolean
function Entity:SetIKTarget(chain, target, rotationOrMatch) end

---Removes a chain's target: the chain idles, or Ground chains place the foot on the ground again.
---@param chain string
---@return boolean
function Entity:ClearIKTarget(chain) end

---Fades a chain's weight (0..1) linearly over seconds (default 0: at once). False for an unknown chain or an
---invalid weight or time.
---@param chain string
---@param weight number
---@param seconds? number
---@return boolean
function Entity:SetIKWeight(chain, weight, seconds) end

---A chain's current weight; nil for an unknown chain.
---@param chain string
---@return number?
function Entity:GetIKWeight(chain) end

---Holds every mesh node's morph target of this name at weight (0..1), fading linearly over seconds (default 0) from the
---weight shown, until ClearMorphWeight. False for an unknown target or an invalid weight or time.
---@param target string
---@param weight number
---@param seconds? number
---@return boolean
function Entity:SetMorphWeight(target, weight, seconds) end

---The morph target's weight shown (of the first mesh node with it); nil for an unknown target.
---@param target string
---@return number?
function Entity:GetMorphWeight(target) end

---Returns the target (with nil, every target) to its animated weight. False when no script weight was set or for an
---unknown target ("" is a target name).
---@param target? string
---@return boolean
function Entity:ClearMorphWeight(target) end

---The model's unique morph target names, in node index (glTF) order.
---@return string[]
function Entity:GetMorphTargets() end

---Activates passive skeleton physics. Inherits linear and rigid-body angular motion; impulse is total world impulse in N*s.
---Returns false and logs invalid rigs/settings/values or callback cancellation. Missing Ragdoll or a wrong impulse type raises.
---@param impulse? Vec3
---@return boolean
function Entity:ActivateRagdoll(impulse) end

---Removes the physical bodies and blends the frozen pose back to animation. Empty clip keeps current playback.
---Moves the entity horizontally with the fall; gameplay places its height for a different ground level.
---@param clip string
---@param seconds number # 0..60
---@return boolean
function Entity:RecoverRagdoll(clip, seconds) end

---True while physical bodies drive this entity, including sleeping bodies; false during recovery.
---@return boolean
function Entity:IsRagdollActive() end

---Restarts every SpringBone chain on the animated pose, at rest, on the next update (after a cut the automatic teleport
---detection misses). Errors without a SpringBone component.
function Entity:ResetSpringBones() end

---Starts a new ParticleEmitter cycle unless it is playing.
function Entity:PlayParticles() end

---Stops emitting; clear also removes the live particles.
---@param clear? boolean
function Entity:StopParticles(clear) end

---Emits up to count (0..10000) particles at once; returns how many fit.
---@param count integer
---@return integer
function Entity:EmitParticles(count) end

---Whether the ParticleEmitter is playing.
---@return boolean
function Entity:IsEmittingParticles() end

---Live particles of the ParticleEmitter.
---@return integer
function Entity:GetParticleCount() end

---The entity's script instance, or nil.
---@return BasaltScript?
function Entity:GetScript() end

---Destroys the entity (with its children) at the end of the frame.
function Entity:Destroy() end

